-- CoA Custom races: the four racials of every race from 12 up (spell_dbc 14000000-14009999).
-- Source: 7_coa_racials_1.5.sql of the CoA Custom 1.5.1 installer package.
DELETE FROM `playercreateinfo_spell_custom` WHERE `Note` LIKE 'racial combo:%';
-- CoA Custom 1.5: racials of the non-vanilla races (gen_coa_racials.py)
DELETE FROM `spell_dbc` WHERE `ID` BETWEEN 14000000 AND 14009999;
